def solve(grid):
    """Count the number of islands (connected groups of 1s) in the grid.
    Cells are connected orthogonally (up, down, left, right).
    Args:
        grid (list of list of int): 2D grid of 0s and 1s.
    Returns:
        int: number of islands.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
