{"task_id": "T39", "code": "def solve(word1, word2):
    """Return the Levenshtein edit distance between two strings.
    Operations allowed: insertion, deletion, substitution, each cost 1.
    """
    m, n = len(word1), len(word2)
    # DP table of size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # deletion
                                   dp[i][j - 1],    # insertion
                                   dp[i - 1][j - 1])  # substitution
    return dp[m][n]"}

{"task_id":"T37","code":"def solve(nums):
    n=len(nums)
    if n<=1:
        return nums[:]
    # find pivot
    i=n-2
    while i>=0 and nums[i]>=nums[i+1]:
        i-=1
    if i==-1:
        return sorted(nums)
    # find rightmost successor greater than pivot
    j=n-1
    while nums[j]<=nums[i]:
        j-=1
    res=nums[:]
    res[i],res[j]=res[j],res[i]
    res[i+1:]=reversed(res[i+1:])
    return res
"}

