def solve(grid):
    """Count islands in a grid where any non-zero value is considered land.
    Handles empty grid and non-rectangular rows gracefully.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    visited = [[False]*cols for _ in range(rows)]
    def is_land(r, c):
        # Return True if cell exists and is non-zero.
        if c < 0 or c >= len(grid[r]):
            return False
        return grid[r][c] != 0
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if y < 0 or y >= len(grid[x]) or visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and is_land(nx, ny) and not visited[nx][ny]:
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and is_land(i, j):
                count += 1
                dfs(i, j)
    return count

